function largestAfterOneFlip(num: number): number {
  let best = 0;
  for (let rest = num, p = 1; rest > 0; rest = Math.floor(rest / 10), p *= 10) {
    if (rest % 10 === 6) best = p; // keeps overwriting, so the leftmost 6 wins
  }
  return num + 3 * best;
}

